//! Emit `app/lib/design/tokens/*.g.dart` from validated tokens.

use std::fmt::Write as _;
use std::path::PathBuf;

use super::output::Output;
use super::tokens::{
    OPACITY_KEYS, ROLES, Rgb, SHAPE_KEYS, SIZE_KEYS, SPACE_KEYS, THEMES, TYPE_STEPS, Tokens,
};

const HEADER: &str =
    "// GENERATED by cargo xtask brand from brand/. Do not edit.\n// dart format off\n";
const DIR: &str = "app/lib/design/tokens";

/// A Dart double literal: `4.0`, `0.12`, `-0.5`.
fn dbl(v: f64) -> String {
    if v.fract() == 0.0 {
        format!("{v:.1}")
    } else {
        format!("{v}")
    }
}

fn camel_hex(c: Rgb) -> String {
    format!("Color(0xFF{:02X}{:02X}{:02X})", c.0, c.1, c.2)
}

fn out(name: &str, body: &str) -> Output {
    Output {
        path: PathBuf::from(format!("{DIR}/{name}.g.dart")),
        bytes: format!("{HEADER}{body}").into_bytes(),
        binary: false,
    }
}

fn colors(t: &Tokens) -> String {
    let roles: Vec<&str> = ROLES
        .iter()
        .copied()
        .filter(|r| t.themes.get("light").is_some_and(|l| l.contains_key(*r)))
        .collect();
    let mut s = String::from("import 'package:flutter/material.dart';\n\n");
    s.push_str("/// Semantic colors of one theme. Values come from brand/tokens.toml.\n");
    s.push_str("class LsColors extends ThemeExtension<LsColors> {\n  const LsColors({\n    required this.brightness,\n");
    for r in &roles {
        let _ = writeln!(s, "    required this.{r},");
    }
    s.push_str("  });\n\n  final Brightness brightness;\n");
    for r in &roles {
        let _ = writeln!(s, "  final Color {r};");
    }
    for theme in THEMES.iter().filter(|th| t.themes.contains_key(**th)) {
        let b = if theme.starts_with("light") {
            "light"
        } else {
            "dark"
        };
        let _ = write!(
            s,
            "\n  static const LsColors {theme} = LsColors(\n    brightness: Brightness.{b},\n"
        );
        for r in &roles {
            let _ = writeln!(s, "    {r}: {},", camel_hex(t.color(theme, r)));
        }
        s.push_str("  );\n");
    }
    s.push_str("\n  @override\n  LsColors copyWith({\n    Brightness? brightness,\n");
    for r in &roles {
        let _ = writeln!(s, "    Color? {r},");
    }
    s.push_str("  }) {\n    return LsColors(\n      brightness: brightness ?? this.brightness,\n");
    for r in &roles {
        let _ = writeln!(s, "      {r}: {r} ?? this.{r},");
    }
    s.push_str("    );\n  }\n\n  @override\n  LsColors lerp(ThemeExtension<LsColors>? other, double t) {\n");
    s.push_str("    if (other is! LsColors) return this;\n    return LsColors(\n");
    s.push_str("      brightness: t < 0.5 ? brightness : other.brightness,\n");
    for r in &roles {
        let _ = writeln!(s, "      {r}: Color.lerp({r}, other.{r}, t)!,");
    }
    s.push_str("    );\n  }\n}\n");
    s
}

fn cap(s: &str) -> String {
    let mut c = s.chars();
    c.next().map_or_else(String::new, |f| {
        f.to_uppercase().collect::<String>() + c.as_str()
    })
}

fn text(t: &Tokens) -> String {
    let mut s = String::from(
        "import 'package:flutter/painting.dart';\n\n/// Type families and the text scale.\nabstract final class LsType {\n",
    );
    for (k, v) in &t.families {
        let _ = writeln!(s, "  static const String font{} = '{v}';", cap(k));
    }
    for name in TYPE_STEPS.iter().filter(|n| t.scale.contains_key(**n)) {
        let st = &t.scale[*name];
        let _ = write!(
            s,
            "\n  static const TextStyle {name} = TextStyle(\n    fontFamily: font{},\n    fontSize: {},\n    fontWeight: FontWeight.w{},\n    height: {:.4},\n    letterSpacing: {},\n  );\n",
            cap(&st.family),
            dbl(st.size),
            st.weight,
            st.height / st.size,
            dbl(st.tracking),
        );
    }
    s.push_str("}\n");
    s
}

fn doubles(
    class: &str,
    doc: &str,
    keys: &[&str],
    map: &std::collections::BTreeMap<String, f64>,
) -> String {
    let mut s = format!("/// {doc}\nabstract final class {class} {{\n");
    for k in keys.iter().filter(|k| map.contains_key(**k)) {
        let _ = writeln!(s, "  static const double {k} = {};", dbl(map[*k]));
    }
    s.push_str("}\n");
    s
}

fn motion(t: &Tokens) -> String {
    let mut s = String::from(
        "import 'package:flutter/animation.dart';\n\n/// Durations and curves.\nabstract final class LsMotion {\n",
    );
    for (k, v) in &t.durations {
        let _ = writeln!(
            s,
            "  static const Duration {k} = Duration(milliseconds: {v});"
        );
    }
    for (k, c) in &t.curves {
        let _ = writeln!(
            s,
            "  static const Cubic {k} = Cubic({}, {}, {}, {});",
            dbl(c[0]),
            dbl(c[1]),
            dbl(c[2]),
            dbl(c[3])
        );
    }
    s.push_str("}\n");
    s
}

/// The seven token files.
pub fn emit(t: &Tokens) -> Vec<Output> {
    vec![
        out("colors", &colors(t)),
        out("type", &text(t)),
        out(
            "space",
            &doubles(
                "LsSpace",
                "Spacing scale in logical px.",
                &SPACE_KEYS,
                &t.space,
            ),
        ),
        out(
            "size",
            &doubles("LsSize", "Fixed sizes in logical px.", &SIZE_KEYS, &t.size),
        ),
        out(
            "shape",
            &doubles(
                "LsShape",
                "Corner radii in logical px.",
                &SHAPE_KEYS,
                &t.shape,
            ),
        ),
        out(
            "opacity",
            &doubles("LsOpacity", "State opacities.", &OPACITY_KEYS, &t.opacity),
        ),
        out("motion", &motion(t)),
    ]
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::brand::tokens::TypeStyle;
    use std::collections::BTreeMap;

    fn tokens() -> Tokens {
        let mut themes = BTreeMap::new();
        for (name, a, b) in [
            ("light", Rgb(0xEC, 0xE9, 0xE3), Rgb(0x1E, 0x1B, 0x19)),
            ("dark", Rgb(0x1E, 0x1B, 0x19), Rgb(0xEC, 0xE9, 0xE3)),
        ] {
            let roles = BTreeMap::from([("surface".to_owned(), a), ("onSurface".to_owned(), b)]);
            themes.insert(name.to_owned(), roles);
        }
        let n = |pairs: &[(&str, f64)]| {
            pairs
                .iter()
                .map(|(k, v)| ((*k).to_owned(), *v))
                .collect::<BTreeMap<_, _>>()
        };
        Tokens {
            palette: BTreeMap::new(),
            themes,
            families: BTreeMap::from([
                ("display".to_owned(), "Space Grotesk".to_owned()),
                ("body".to_owned(), "Inter".to_owned()),
                ("mono".to_owned(), "JetBrains Mono".to_owned()),
            ]),
            scale: BTreeMap::from([(
                "display".to_owned(),
                TypeStyle {
                    family: "display".into(),
                    size: 40.0,
                    weight: 700,
                    height: 48.0,
                    tracking: -0.5,
                },
            )]),
            space: n(&[("xs", 4.0)]),
            size: n(&[("target", 48.0)]),
            shape: n(&[("radiusSm", 6.0)]),
            opacity: n(&[("pressed", 0.12)]),
            durations: BTreeMap::from([("fast".to_owned(), 100)]),
            curves: BTreeMap::from([("standard".to_owned(), [0.2, 0.0, 0.0, 1.0])]),
        }
    }

    fn file(outs: &[Output], name: &str) -> String {
        let o = outs.iter().find(|o| o.path.ends_with(name)).expect(name);
        String::from_utf8(o.bytes.clone()).unwrap()
    }

    #[test]
    fn colors_file_matches_expected() {
        let expected = "\
// GENERATED by cargo xtask brand from brand/. Do not edit.
// dart format off
import 'package:flutter/material.dart';

/// Semantic colors of one theme. Values come from brand/tokens.toml.
class LsColors extends ThemeExtension<LsColors> {
  const LsColors({
    required this.brightness,
    required this.surface,
    required this.onSurface,
  });

  final Brightness brightness;
  final Color surface;
  final Color onSurface;

  static const LsColors light = LsColors(
    brightness: Brightness.light,
    surface: Color(0xFFECE9E3),
    onSurface: Color(0xFF1E1B19),
  );

  static const LsColors dark = LsColors(
    brightness: Brightness.dark,
    surface: Color(0xFF1E1B19),
    onSurface: Color(0xFFECE9E3),
  );

  @override
  LsColors copyWith({
    Brightness? brightness,
    Color? surface,
    Color? onSurface,
  }) {
    return LsColors(
      brightness: brightness ?? this.brightness,
      surface: surface ?? this.surface,
      onSurface: onSurface ?? this.onSurface,
    );
  }

  @override
  LsColors lerp(ThemeExtension<LsColors>? other, double t) {
    if (other is! LsColors) return this;
    return LsColors(
      brightness: t < 0.5 ? brightness : other.brightness,
      surface: Color.lerp(surface, other.surface, t)!,
      onSurface: Color.lerp(onSurface, other.onSurface, t)!,
    );
  }
}
";
        assert_eq!(file(&emit(&tokens()), "colors.g.dart"), expected);
    }

    #[test]
    fn type_file_has_height_and_tracking() {
        let s = file(&emit(&tokens()), "type.g.dart");
        assert!(s.starts_with(
            "// GENERATED by cargo xtask brand from brand/. Do not edit.\n// dart format off\n"
        ));
        assert!(s.contains("height: 1.2000,"), "{s}");
        assert!(s.contains("letterSpacing: -0.5,"), "{s}");
        assert!(s.contains("fontWeight: FontWeight.w700,"), "{s}");
        assert!(s.contains("fontFamily: fontDisplay,"), "{s}");
        assert!(
            s.contains("static const String fontMono = 'JetBrains Mono';"),
            "{s}"
        );
    }

    #[test]
    fn motion_file_has_duration_and_cubic() {
        let s = file(&emit(&tokens()), "motion.g.dart");
        assert!(s.contains("Duration(milliseconds: 100)"), "{s}");
        assert!(s.contains("Cubic(0.2, 0.0, 0.0, 1.0)"), "{s}");
    }

    #[test]
    fn numeric_files_emit_doubles() {
        let outs = emit(&tokens());
        assert!(file(&outs, "space.g.dart").contains("static const double xs = 4.0;"));
        assert!(file(&outs, "size.g.dart").contains("static const double target = 48.0;"));
        assert!(file(&outs, "opacity.g.dart").contains("static const double pressed = 0.12;"));
        assert_eq!(outs.len(), 7);
    }
}
